SELECT IFNULL(sum( device_num ),0) as device_count_total, IFNULL(sum( dev_online_num ),0) as dev_count_online, IFNULL(sum( dev_offline_num ),0) as dev_count_offline, IFNULL(sum( channel_num ),0) as channel_count_total, IFNULL(sum( channel_online_num ),0) as channel_count_online, IFNULL(sum( channel_offline_num ),0) as channel_count_offline FROM vm_statistics_devices t
AND `year` = YEAR(NOW()) AND `month` = MONTH(NOW()) AND `day` = DAY(NOW())
and t.industry_code = #{industryCode}
and t.tenant_id = #{tenantId}

select distinct device_code, status
from (SELECT od.device_code, d.device_status as status, od.tenant_id , t.industry_code, t.app_ver_code
FROM vm_organ_device_rel_t od
LEFT JOIN vm_device_info_t d ON od.device_code = d.device_code and d.delete_flag = '0'
LEFT JOIN vm_order_devices t ON t.tenant_id = od.tenant_id and t.delete_flag = '0' and t.device_code = od.device_code
WHERE od.delete_flag = '0' and od.device_type = 4 and t.ord_status in (0,1,2)
and t.tenant_id = #{tenantId}

    and t.industry_code = #{industryCode}

) dataTable
 ${dataScope}

SELECT
    COUNT(IF(`status` = '0',1,null)) AS devCountOnline,
    COUNT(IF(`status` = '1',1,null)) AS devCountOffline,
    COUNT(`status`) AS deviceCountTotal
FROM(
        SELECT DISTINCT dataTable.device_code, d.device_status as `status` FROM vm_order_devices dataTable
            INNER JOIN vm_device_info_t d ON dataTable.device_code = d.device_code
            LEFT JOIN vm_channel_info_t ci ON ci.device_code = dataTable.device_code
WHERE  d.delete_flag = '0' AND dataTable.delete_flag = '0' and dataTable.ord_status in (0,1,2) and ci.delete_flag = '0'


